with customer_summary as (select customer_id, round((100 * sum(case when status = 'FROZEN' then 1 else 0 end)) / count(*), 1) as pct_frozen, sum(balance) as total_balance from accounts where account_type != 'CREDIT' group by customer_id) select c.credit_limit, cs.pct_frozen, cs.total_balance from customers c inner join customer_summary cs on c.id = cs.customer_id where cs.total_balance > 375000 order by total_balance desc;
